head.script:

    scwin.onpageload = function() {

		var jsonData = [{col1:"a",col2:"a1",col3:"1000", col4:"a"}
						,{col1:"a",col2:"a2",col3:"20", col4:"a"}
                        ,{col1:"a",col2:"a3",col3:"100", col4:"a"}
                        ,{col1:"a",col2:"a4",col3:"2000", col4:"a"}
                        ,{col1:"a",col2:"a5",col3:"1500", col4:"a"}
                        ,{col1:"a",col2:"a6",col3:"11500", col4:"a"}
                        ,{col1:"a",col2:"a7",col3:"21500", col4:"a"}
                        ,{col1:"a",col2:"a8",col3:"500", col4:"a"}
                        ,{col1:"a",col2:"a9",col3:"4500", col4:"a"}
                        ,{col1:"a",col2:"a10",col3:"1500", col4:"a"}
                        ,{col1:"a",col2:"a11",col3:"1500", col4:"a"}
                        ,{col1:"a",col2:"a12",col3:"1500", col4:"a"}
                        ,{col1:"a",col2:"a12",col3:"1500", col4:"a"}];
		dataList1.setJSON(jsonData);

		gridView1.setMaxLength("col1",2);
    };

    scwin.onpageunload = function() {

    };

	scwin.checkVal = function() {
		return WebSquare.wUnit.getJq("#gridView1_cell_2_2").css("background-color") == 'rgb(252, 167, 60)';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_6_2').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column5').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column5').click()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
